--- app/views/moderate/questions/_form.html.erb ---
<%= form_with model: [:moderate, @quiz, @question] do |form| %>
  <% if @question.errors.any? %>
    <div class="errors" role="alert">
      <ul>
        <% @question.errors.full_messages.each do |message| %>
          <li><%= message %></li>
        <% end %>
      </ul>
    </div>
  <% end %>

  <div class="field">
    <%= form.label :body, "Question" %>
    <%= form.text_area :body, class: "input", rows: 3, required: true, autofocus: true %>
  </div>

  <div class="field">
    <span class="field-label">Options</span>
    <span class="field-hint">Mark the correct options, at least one. Empty rows are skipped.</span>
  </div>

  <div class="option-rows" data-option-rows data-next-option-index="<%= @option_rows.length %>">
    <% @option_rows.each_with_index do |option, index| %>
      <%= render "option_row", option: option, index: index %>
    <% end %>
  </div>
  <div class="buttons option-add-button">
    <%= button_tag "Add option", type: "button", class: "btn btn--ghost btn--sm", data: { add_option: true } %>
  </div>

  <div class="field active-field">
    <label class="checkbox">
      <%= form.check_box :active %>
      <span>Active</span>
    </label>
    <span class="field-hint">Only active questions are played.</span>
  </div>

  <div class="buttons">
    <%= form.submit "Save question", class: "btn btn--pink" %>
    <%= link_to "Cancel", moderate_quiz_path(@quiz), class: "btn btn--ghost" %>
  </div>
<% end %>
--- app/controllers/moderate/base_controller.rb ---
module Moderate
  class BaseController < ApplicationController
    before_action :authenticate_moderator!

    private

    def authenticate_moderator!
      authenticate_or_request_with_http_basic("Quizzy Moderator") do |username, password|
        expected_username = ENV["QUIZZY_MODERATOR_USERNAME"].to_s
        expected_password = ENV["QUIZZY_MODERATOR_PASSWORD"].to_s

        expected_username.present? && expected_password.present? &&
          ActiveSupport::SecurityUtils.secure_compare(username.to_s, expected_username) &&
          ActiveSupport::SecurityUtils.secure_compare(password.to_s, expected_password)
      end
    end
  end
end
